aad  # combo_id=1 row_id=1 combo_index=0 mnemonic=aad expected_valid=False mode_support=Invalid
aad 1  # combo_id=2 row_id=2 combo_index=0 mnemonic=aad expected_valid=False mode_support=Invalid
aad 0x7f  # combo_id=7278 row_id=2 combo_index=1 mnemonic=aad expected_valid=False mode_support=Invalid note=variant:imm_max
aam  # combo_id=3 row_id=3 combo_index=0 mnemonic=aam expected_valid=False mode_support=Invalid
